from math import gcd

def order(base, modulus):
    if gcd(base, modulus) != 1:
        return 0
    phi = modulus - modulus // gcd(modulus, 2) if modulus % 2 == 0 and modulus > 2 else modulus - 1

    # A more robust way is to calculate phi(modulus) properly
    def phi(n):
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    phi_m = phi(modulus)

    # Find prime factorization of phi_m
    factors = set()
    n = phi_m
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.add(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.add(n)

    # Test divisors of phi_m
    order_val = phi_m

    for p in factors:
        exponent = phi_m // p
        while order_val % p == 0 and pow(base, exponent, modulus) == 1:
            order_val = exponent
            exponent //= p

    return order_val

